$ErrorActionPreference = "Stop"
$path = Join-Path (Get-Location) "backend\app\exchanges\adapters\binance.py"
$data = [Convert]::FromBase64String("")
[IO.File]::WriteAllBytes($path, $data)
Write-Host "binance.py replaced: $path"
docker compose run --rm backend python -m py_compile /app/app/exchanges/adapters/binance.py
if ($LASTEXITCODE -ne 0) { throw "Python syntax check failed" }
Write-Host "OK: binance.py syntax is valid"
